34	          min: 1800,
35	        };
36	
37	  const [line, setLine] = useState(0);
38	
39	  useEffect(() => {
40	    const cycle = setInterval(() => setLine((n) => (n + 1) % copy.lines.length), 700);
41	    // held for the minimum even when the real work finishes first, so it reads
42	    // as thought rather than a flash
43	    const done = setTimeout(onDone, copy.min);
44	    return () => {
45	      clearInterval(cycle);
46	      clearTimeout(done);
47	    };
48	    // eslint-disable-next-line react-hooks/exhaustive-deps
49	  }, [variant]);
50	
51	  return (
52	    <Screen center>
53	      <DrawingArc />
54	      <p className="ob-sub" style={{ maxWidth: 280, marginTop: 30 }}>
55	        {copy.title}
56	      </p>
57	      <p className="ob-loading-status" aria-live="polite">
58	        {copy.lines[line]}
59	      </p>
60	    </Screen>
61	  );
62	}
