206	export function Recommendations({
207	  goalIds,
208	  currentStack,
209	  diet,
210	  reactions,
211	  forms,
212	  age,
213	  sex,
214	  onDone,
215	}: {
216	  goalIds: string[];
217	  currentStack: string[];
218	  diet: string[];
219	  reactions: string[];
220	  forms: string[];
221	  age?: number | null;
222	  sex?: 'm' | 'f' | 'na' | null;
223	  onDone: (picks: Recommendation[]) => void;
224	}) {
225	  const data = useRecommendations(goalIds, currentStack, diet, reactions, forms, age, sex);
226	  const [picks, setPicks] = useState<Recommendation[] | null>(null);
227	
228	  useEffect(() => {
229	    if (data && !picks) setPicks(data.picks);
230	  }, [data, picks]);
231	
232	  if (!data || !picks) {
233	    return (
234	      <Screen center>
235	        <p className="ob-sub">Loading…</p>
236	      </Screen>
237	    );
238	  }
239	
240	  const chosen = picks.filter((p) => p.selected);
241	
242	  return (
243	    <Screen
244	      scroll
245	      footer={
246	        <Cta onClick={() => onDone(chosen)} disabled={chosen.length === 0}>
247	          Create schedule
248	        </Cta>
249	      }
250	    >
251	      <Title>What we found</Title>
252	      <Sub>
253	        Matched to {data.leftOut.goalNames.join(' and ').toLowerCase()}, then ranked by what you
254	        told us — what you don’t eat, what hasn’t agreed with you, and the strength of the
255	        evidence. Untick anything you don’t want.
256	      </Sub>
257	
258	      <div className="ob-recs">
259	        {picks.map((r) => (
260	          <button
261	            key={r.id}
262	            className={`ob-rec${r.selected ? ' on' : ''}`}
263	            aria-pressed={r.selected}
264	            onClick={() =>
265	              setPicks((ps) => ps!.map((p) => (p.id === r.id ? { ...p, selected: !p.selected } : p)))
266	            }
267	          >
268	            <span className="ob-rec-main">
269	              <span className="ob-card-title">{r.name}</span>
270	              {/* The app holds no dose for anything and will not invent one --
271	                  the glossary carries category, mechanism, storage and route,
272	                  never an amount. See legal.md. The slot stays, labelled. */}
273	              <span className="ob-rec-dose">{doseLine(r)}</span>
274	              {/* No rule fired and no goal tag matched — a card with no
275	                  explanation beats a card with an invented one. */}
276	              {r.why && <span className="ob-rec-why">{r.why}</span>}
277	              <span className="ob-rec-link">Read the research →</span>
278	            </span>
279	            <span className={`ob-tick${r.selected ? ' on' : ''}`}>
280	              {r.selected && (
281	                <svg width="12" height="12" viewBox="0 0 12 12" fill="none" stroke="var(--bg)" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
282	                  <path d="M2.5 6.2 4.8 8.5 9.5 3.5" />
283	                </svg>
284	              )}
285	            </span>
286	          </button>
287	        ))}
288	      </div>
289	
290	      {/* The part people screenshot. Do not cut it. */}
291	      <div className="ob-left-out">
292	        <h2>What was left out</h2>
293	        {data.leftOut.alreadyTaking.length > 0 && (
294	          <p>
295	            <b>Already in your stack:</b> {data.leftOut.alreadyTaking.join(', ')}. No point suggesting
296	            what you are taking.
297	          </p>
298	        )}
299	        {/* A product swapped for another form of the same nutrient. Left
300	            silent this reads as the app ignoring an answer. */}
301	        {data.leftOut.swapped.length > 0 && (
302	          <p>
303	            <b>Swapped for another form:</b>{' '}
304	            {data.leftOut.swapped
305	              .slice(0, 4)
306	              .map((s) => `${s.name} — ${s.why}`)
307	              .join('. ')}
308	            .
309	          </p>
310	        )}
311	        {data.leftOut.noMatch.length > 0 && (
312	          <p>
313	            <b>Matched but ranked lower:</b> {data.leftOut.noMatch.slice(0, 6).join(', ')}. Fewer of
314	            your goals matched, or something you told us moved another one above them.
315	          </p>
316	        )}
317	        <p>
318	          Everything else in the library is tagged for goals you did not pick. Nothing was excluded
319	          for being unpopular or unprofitable — the ranking is your goals, your answers and the
320	          strength of the evidence, and nothing else.
321	        </p>
322	      </div>
323	    </Screen>
324	  );
325	}
