327	/* ── the draggable schedule ──────────────────────────────────────────── */
328	
329	interface Slot {
330	  id: string;
331	  name: string;
332	  time: string;
333	}
334	
335	const buildSlots = (meals: Meal[], wake: string, sleep: string): Slot[] => {
336	  const s: Slot[] = [{ id: 'morning', name: 'Morning', time: wake }];
337	  for (const m of [...meals].sort((a, b) => toMinutes(a.time) - toMinutes(b.time))) {
338	    s.push({ id: m.id, name: m.name, time: m.time });
339	  }
340	  s.push({ id: 'winddown', name: 'Wind-down', time: fromMinutes(toMinutes(sleep) - 60) });
341	  const seen = new Set<string>();
342	  return s.filter((x) => (seen.has(x.time) ? false : (seen.add(x.time), true)));
343	};
344	
345	export function ScheduleBuilder({
346	  picks,
347	  meals,
348	  wake,
349	  sleep,
350	  onDone,
351	}: {
352	  picks: Recommendation[];
353	  meals: Meal[];
354	  wake: string;
355	  sleep: string;
356	  onDone: (schedule: { id: string; time: string }[]) => void;
357	}) {
358	  const slots = useMemo(() => buildSlots(meals, wake, sleep), [meals, wake, sleep]);
359	  const [placed, setPlaced] = useState<Record<string, string>>(() =>
360	    Object.fromEntries(picks.map((p, i) => [p.id, slots[i % slots.length].id])),
361	  );
362	  const [dragging, setDragging] = useState<string | null>(null);
363	  const [over, setOver] = useState<{ slot: string; bad: boolean } | null>(null);
364	  const [shake, setShake] = useState<string | null>(null);
365	  const [message, setMessage] = useState<string | null>(null);
366	  const hold = useRef<number | null>(null);
367	
368	  const ctx = { mealTimes: meals.map((m) => m.time), sleepTime: sleep };
369	  const slotById = Object.fromEntries(slots.map((s) => [s.id, s]));
370	
371	  const itemsIn = (slotId: string) => picks.filter((p) => placed[p.id] === slotId);
372	
373	  const others = (movingId: string): ScheduledItem[] =>
374	    picks
375	      .filter((p) => p.id !== movingId)
376	      .map((p) => ({ id: p.id, name: p.name, time: slotById[placed[p.id]]?.time ?? wake }));
377	
378	  const tryDrop = (id: string, slotId: string) => {
379	    const p = picks.find((x) => x.id === id)!;
380	    const target = slotById[slotId];
381	    const violations = checkPlacement({ id, name: p.name, time: target.time }, target.time, others(id), ctx);
382	    const blocking = violations.find((v) => v.severity === 'block');
383	    if (blocking) {
384	      // springs back, shakes, and says which rule -- the shake on its own
385	      // communicates nothing and fails accessibility
386	      setShake(id);
387	      setMessage(blocking.message);
388	      setTimeout(() => setShake(null), 420);
389	      return;
390	    }
391	    setPlaced((m) => ({ ...m, [id]: slotId }));
392	    setMessage(violations[0]?.message ?? null);
393	  };
394	
395	  const startHold = (id: string) => {
396	    hold.current = window.setTimeout(() => setDragging(id), 200);
397	  };
398	  const cancelHold = () => {
399	    if (hold.current) clearTimeout(hold.current);
400	    hold.current = null;
401	  };
402	
403	  const onMove = (e: React.PointerEvent) => {
404	    if (!dragging) return;
405	    const el = document.elementFromPoint(e.clientX, e.clientY)?.closest('[data-slot]') as HTMLElement | null;
406	    if (!el) return setOver(null);
407	    const slotId = el.dataset.slot!;
408	    const p = picks.find((x) => x.id === dragging)!;
409	    const t = slotById[slotId];
410	    const bad = checkPlacement({ id: dragging, name: p.name, time: t.time }, t.time, others(dragging), ctx).some(
411	      (v) => v.severity === 'block',
412	    );
413	    setOver({ slot: slotId, bad });
414	  };
415	
416	  const onUp = () => {
417	    cancelHold();
418	    if (dragging && over) tryDrop(dragging, over.slot);
419	    setDragging(null);
420	    setOver(null);
421	  };
422	
423	  return (
424	    <Screen
425	      scroll
426	      footer={<Cta onClick={() => onDone(picks.map((p) => ({ id: p.id, time: slotById[placed[p.id]].time })))}>Start</Cta>}
427	    >
428	      <Title>Your schedule</Title>
429	      <Sub>Press and hold a card to move it. We’ll say if something can’t go there.</Sub>
430	
431	      <div className="ob-slots" onPointerMove={onMove} onPointerUp={onUp} onPointerCancel={onUp}>
432	        {slots.map((s) => (
433	          <div key={s.id}>
434	            <div className="ob-slot-head">
435	              <span className="ob-slot-name">{s.name}</span>
436	              <span className="ob-slot-time">{s.time}</span>
437	            </div>
438	            <div
439	              data-slot={s.id}
440	              className={`ob-slot${over?.slot === s.id ? (over.bad ? ' over-bad' : ' over') : ''}`}
441	            >
442	              {itemsIn(s.id).length === 0 && <div className="ob-slot-empty">Nothing here</div>}
443	              {itemsIn(s.id).map((p) => (
444	                <div
445	                  key={p.id}
446	                  className={`ob-dose-card${dragging === p.id ? ' lifted' : ''}${shake === p.id ? ' shake' : ''}`}
447	                  onPointerDown={() => startHold(p.id)}
448	                  onPointerUp={cancelHold}
449	                  onContextMenu={(e) => e.preventDefault()}
450	                >
451	                  <span className="ob-dose-time">{s.time}</span>
452	                  <span style={{ flex: 1, minWidth: 0 }}>
453	                    <span className="ob-card-title" style={{ display: 'block' }}>
454	                      {p.name}
455	                    </span>
456	                    <span className="ob-caption">{p.route} · you set the amount</span>
457	                  </span>
458	                  <svg className="ob-dose-grip" width="16" height="16" viewBox="0 0 16 16" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" aria-hidden>
459	                    <path d="M3 5.5h10M3 10.5h10" />
460	                  </svg>
461	                </div>
462	              ))}
463	            </div>
464	          </div>
465	        ))}
466	      </div>
467	
468	      {message && (
469	        <div className="ob-conflict" role="alert" aria-live="assertive">
470	          {message}
471	        </div>
472	      )}
473	    </Screen>
474	  );
475	}
476	
477	/* ── done ────────────────────────────────────────────────────────────── */
478	
479	export function Done({ onFinish }: { onFinish: () => void }) {
480	  useEffect(() => {
481	    const t = setTimeout(onFinish, 1400);
482	    return () => clearTimeout(t);
483	  }, [onFinish]);
484	
485	  return (
486	    <Screen center>
487	      <OnboardIllustration name="done" size={110} />
488	      <div style={{ marginTop: 26 }}>
489	        <Title>You’re set</Title>
490	        <Sub>Your first day is on the Today screen.</Sub>
491	      </div>
492	    </Screen>
493	  );
494	}
