1	import { expect, type Page } from '@playwright/test';
2	import { STUB_EMAIL } from './catalogue';
3	
4	/**
5	 * One driver, twenty answers.
6	 *
7	 * `onboarding.spec.ts` walks the flow as a straight line: screen, assert,
8	 * click, next line. That is the right shape for one happy path and the wrong
9	 * shape for twenty, because half of what is worth testing is the flow *not*
10	 * going in a straight line — a question retired by an earlier answer, a step
11	 * re-opened by going back, a store restored from a kill.
12	 *
13	 * So this is a loop instead. It reads `data-step` off `.ob-root`, does whatever
14	 * the persona says for that screen, and waits for the step to change. Nothing
15	 * here knows the order of the flow, which means moving a screen in `FLOW`
16	 * cannot make these pass while the product is broken.
17	 */
18	
19	/** Cleared by the six-character rule on the form and by nothing else. */
20	const FORM_PASSWORD = 'smoke-account';
21	
22	/** `KEY` in src/onboarding/store.ts. */
23	export const STORE_KEY = 'pepstack.onboarding.v1';
24	
25	export interface Persona {
26	  /** 1..20, the number in section 5 of PROMPT_PERSONALISATION.md */
27	  n: number;
28	  name: string;
29	  /** what this run is for, in one line. Printed with the report. */
30	  watch: string;
31	
32	  age?: number;
33	  gender?: 'Male' | 'Female' | 'Prefer not to say';
34	  /** option labels to tick; `null` presses Skip; omitted presses Continue */
35	  diet?: string[] | null;
36	  reactions?: string[] | null;
37	  reactionsNote?: string;
38	  forms?: string[] | null;
39	  /** option labels; `null` presses Skip */
40	  q1?: string | null;
41	  q2?: string | null;
42	  q3?: string | null;
43	  wake?: string;
44	  sleep?: string;
45	  /** 'none' deletes every meal the flow starts with */
46	  meals?: 'none';
47	  /** names typed into the search box, catalogue or not */
48	  stack?: string[];
49	  /** goal names exactly as they appear on the cards */
50	  goals?: string[];
51	  notifications?: 'grant' | 'decline';
52	  /** 'restore' presses Restore Purchases first, then buys */
53	  paywall?: 'buy' | 'restore';
54	
55	  /**
56	   * Extra work on a given screen, before the standard handler runs. If the
57	   * hook leaves on a different screen the standard handler is skipped, which
58	   * is what lets one drive the flow backwards mid-run.
59	   */
60	  hooks?: Record<string, (page: Page, run: RunRecord) => Promise<void>>;
61	}
62	
63	export interface ScreenRecord {
64	  step: string;
65	  /** ms spent on the screen, arrival to departure */
66	  ms: number;
67	  /** `aria-valuenow` off the progress bar; null on the screens with no chrome */
68	  progress: number | null;
69	  /** anything clipped, blank, or otherwise wrong about the screen as drawn */
70	  problems: string[];
71	}
72	
73	export interface RunRecord {
74	  persona: string;
75	  /** every screen shown, in the order shown, including any shown twice */
76	  screens: ScreenRecord[];
77	  ms: number;
78	  recommendations: { name: string; dose: string; why: string }[];
79	  /** the subtitle on the recommendations screen, which names the goals used */
80	  matchedTo: string;
81	  /** the "what was left out" block, flattened */
82	  leftOut: string;
83	  schedule: { slot: string; time: string; items: string[] }[];
84	  /** everything the run found, screen-qualified */
85	  problems: string[];
86	  /** appended by a hook, so a persona can record something the driver cannot */
87	  notes: string[];
88	}
89	
90	/**
91	 * The screen currently up, or null once onboarding has handed over.
92	 *
93	 * Read out of the DOM rather than through a locator: the last thing this is
94	 * asked is whether onboarding is still there at all, and a locator would wait
95	 * for an element that has just been unmounted for good.
96	 */
97	export async function currentStep(page: Page): Promise<string | null> {
98	  return page.evaluate(() => document.querySelector('.ob-root')?.getAttribute('data-step') ?? null);
99	}
100	
101	/** `aria-valuenow` off the progress bar; null on the screens with no chrome. */
102	async function progressOf(page: Page): Promise<number | null> {
103	  const raw = await page.evaluate(
104	    () => document.querySelector('.ob-progress')?.getAttribute('aria-valuenow') ?? null,
105	  );
106	  return raw === null ? null : Number(raw);
107	}
108	
109	/**
110	 * What is wrong with the screen as drawn.
111	 *
112	 * Only containers that actually clip are checked. An element overflowing a
113	 * parent with `overflow: visible` is not a defect on its own — it is only a
114	 * defect once something above it cuts it off, and that ancestor is where this
115	 * reports it.
116	 */
117	async function audit(page: Page): Promise<string[]> {
118	  return page.evaluate(async () => {
119	    const root = document.querySelector('.ob-root');
120	    if (!root?.querySelector('.ob-body')) return ['nothing mounted'];
121	    const problems: string[] = [];
122	
123	    /* Let the screen finish sliding in first. Chrome counts a transformed
124	       descendant in its ancestor's scrollable overflow, so a screen measured
125	       mid-animation is 60px wider than the phone on every single screen —
126	       which is a report of nothing, twenty times over. The wrapper's own
127	       animations only: the loading screens run an infinite one underneath
128	       that would never settle. */
129	    const wrapper = document.querySelector('.ob-stage > .ob-screen');
130	    await Promise.all((wrapper?.getAnimations() ?? []).map((a) => a.finished.catch(() => {})));
131	
132	    /* Clipped on purpose: the goal reel pages its neighbours in from off-stage
133	       behind a mask, and the age ruler draws ticks past both ends of the rail
134	       so the numbers keep going as you drag. */
135	    const BY_DESIGN = ['ob-goal-stage', 'ob-ruler'];
136	
137	    const name = (el: HTMLElement) => {
138	      const cls = el.getAttribute('class');
139	      return cls ? `.${cls.trim().split(/\s+/).join('.')}` : el.tagName.toLowerCase();
140	    };
141	
142	    for (const el of [root, ...root.querySelectorAll('*')]) {
143	      if (!(el instanceof HTMLElement)) continue;
144	      if (BY_DESIGN.some((c) => el.classList.contains(c))) continue;
145	      const style = getComputedStyle(el);
146	      if (style.overflowX !== 'visible' && el.scrollWidth > el.clientWidth + 1) {
147	        problems.push(`${name(el)} holds ${el.scrollWidth}px of content in ${el.clientWidth}px`);
148	      }
149	      if (style.overflowY === 'hidden' && el.scrollHeight > el.clientHeight + 1) {
150	        problems.push(
151	          `${name(el)} holds ${el.scrollHeight}px of content in ${el.clientHeight}px and cannot scroll`,
152	        );
153	      }
154	    }
155	
156	    const body = root.querySelector('.ob-body');
157	    if (!(body?.textContent ?? '').trim() && !body?.querySelector('svg, img')) {
158	      problems.push('the body rendered nothing');
159	    }
160	    return problems;
161	  });
162	}
163	
164	/* ── the per-screen handlers ─────────────────────────────────────────── */
165	
166	const cta = (page: Page, name: string | RegExp) => page.getByRole('button', { name, exact: false });
