391	        run.schedule.push({
392	          slot: (await group.locator('.ob-slot-name').innerText()).trim(),
393	          time: (await group.locator('.ob-slot-time').innerText()).trim(),
394	          items: (await group.locator('.ob-dose-card .ob-card-title').allInnerTexts()).map((t) => t.trim()),
395	        });
396	      }
397	      await cta(page, 'Start').click();
398	    },
399	  },
400	
401	  done: {
402	    ready: async (page) => void (await expect(heading(page, /You.re set/)).toBeVisible()),
403	    act: async () => {
404	      /* hands over to the app after 1.4s */
405	    },
406	  },
407	};
408	
409	/* ── the loop ────────────────────────────────────────────────────────── */
410	
411	/** Enough to walk the flow twice over; a loop that never ends fails loudly. */
412	const MAX_TRANSITIONS = 90;
413	
414	export async function runPersona(page: Page, p: Persona): Promise<RunRecord> {
415	  const run: RunRecord = {
416	    persona: `${p.n}. ${p.name}`,
417	    screens: [],
418	    ms: 0,
419	    recommendations: [],
420	    matchedTo: '',
421	    leftOut: '',
422	    schedule: [],
423	    problems: [],
424	    notes: [],
425	  };
426	
427	  await page.goto('/');
428	  const started = Date.now();
429	  /* Hooks fire once each. Two of these personas walk backwards, which means
430	     they see a screen twice — a hook that fired again on the second visit
431	     would put the run in a circle rather than through the branch. */
432	  const fired = new Set<string>();
433	
434	  for (let moves = 0; moves < MAX_TRANSITIONS; moves++) {
435	    const step = await currentStep(page);
436	    if (step === null) break;
437	    const arrived = Date.now();
438	
439	    const handler = HANDLERS[step];
440	    if (!handler) throw new Error(`no handler for step "${step}" — a screen was added to FLOW`);
441	
442	    await handler.ready(page);
443	    const problems = await audit(page);
444	    const entry: ScreenRecord = { step, ms: 0, progress: await progressOf(page), problems };
445	    run.screens.push(entry);
446	    for (const problem of problems) run.problems.push(`${step}: ${problem}`);
447	
448	    const hook = p.hooks?.[step];
449	    if (hook && !fired.has(step)) {
450	      fired.add(step);
451	      await hook(page, run);
452	    }
453	    // a hook that navigated owns the move; acting again would work the wrong screen
454	    if ((await currentStep(page)) === step) await handler.act(page, p, run);
455	
456	    /* Not an expect(locator): the last screen leaves by unmounting the whole
457	       flow, and a negated attribute assertion on an element that no longer
458	       exists fails rather than passes. */
459	    await page.waitForFunction(
460	      (from) => document.querySelector('.ob-root')?.getAttribute('data-step') !== from,
461	      step,
462	      { timeout: 20_000 },
463	    );
464	    entry.ms = Date.now() - arrived;
465	  }
466	
467	  run.ms = Date.now() - started;
468	  if (run.screens.length >= MAX_TRANSITIONS) {
469	    run.problems.push(`the flow never ended: ${MAX_TRANSITIONS} moves and still onboarding`);
470	  }
471	  return run;
472	}
473	
474	/** The persisted store, as the app would read it back on a cold open. */
475	export async function readStore(page: Page): Promise<Record<string, unknown>> {
476	  return page.evaluate((key) => JSON.parse(localStorage.getItem(key) ?? '{}'), STORE_KEY);
477	}
478	
479	/** Rewrite the store and reopen the app on it — a kill and a relaunch. */
480	export async function relaunch(page: Page, patch: Record<string, unknown> = {}): Promise<void> {
481	  await page.evaluate(
482	    ({ key, patch }) => {
483	      const cur = JSON.parse(localStorage.getItem(key) ?? '{}');
484	      localStorage.setItem(key, JSON.stringify({ ...cur, ...patch }));
485	    },
486	    { key: STORE_KEY, patch },
487	  );
488	  await page.reload();
489	}
490	
491	/** One line per screen, for the report. */
492	export function timeline(run: RunRecord): string {
493	  return run.screens.map((s) => s.step).join(' → ');
494	}
