/* ============================================================
   Pepstack onboarding
   Flat black, one accent, generous space. No particles, no
   gradients, no amber. If a screen looks empty that is correct.
   ============================================================ */
:root {
  --accent: #7b5cfa;
  --accent-light: #9c7bff;
  --accent-dim: rgba(123, 92, 250, 0.16);
  --hairline: rgba(255, 255, 255, 0.09);
  --destructive: #ff5a5a;

  --ob-pad: 24px;
  --ob-ease: cubic-bezier(0.2, 0.8, 0.2, 1);
}

.ob-root {
  position: relative;
  height: 100dvh;
  overflow: hidden;
  background: var(--bg);
  color: var(--t1);
  display: flex;
  flex-direction: column;
}

/* ── header: wordmark, progress, back, skip ── */
.ob-header {
  flex: none;
  padding: calc(env(safe-area-inset-top) + 10px) var(--ob-pad) 0;
}
.ob-header-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 34px;
}
.ob-header-spacer {
  width: 44px;
  flex: none;
}
.ob-wordmark {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-weight: 600;
  letter-spacing: -0.3px;
}
.ob-back,
.ob-skip {
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  flex: none;
  color: var(--t2);
  margin: 0 -11px;
}
.ob-skip {
  width: auto;
  padding: 0 11px;
  font-size: 15px;
  font-weight: 500;
}
.ob-progress {
  display: flex;
  gap: 4px;
  margin-top: 14px;
}
.ob-seg {
  flex: 1;
  height: 3px;
  border-radius: 999px;
  background: var(--hairline);
  transition: background-color 240ms var(--ob-ease);
}
.ob-seg.on {
  background: var(--accent);
}

